insert into public.shop3d_categories (slug, name, description, image_url, sort_order) values
('do-choi-in-3d', 'Đồ chơi in 3D', 'Đồ chơi khớp động, xe mô hình, đồ chơi giáo dục in bằng nhựa PLA an toàn.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/83/CreativeTools.se_-_PackshotCreator_-_3D_printed_LEGO_toy_car_%284325785556%29.jpg/1280px-CreativeTools.se_-_PackshotCreator_-_3D_printed_LEGO_toy_car_%284325785556%29.jpg', 1),
('mo-hinh-figure', 'Mô hình & Figure', 'Rồng, chiến binh, mô hình kiến trúc in resin độ chi tiết cao.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7f/CreativeTools.se_-_PackshotCreator_-_3D_printed_dragon_model.jpg/1280px-CreativeTools.se_-_PackshotCreator_-_3D_printed_dragon_model.jpg', 2),
('may-in-3d', 'Máy in 3D', 'Máy in FDM và resin cho người mới, xưởng nhỏ và kỹ sư.', 'https://upload.wikimedia.org/wikipedia/commons/0/01/Prusa_i3_MK2.jpg', 3),
('vat-lieu-in', 'Sợi nhựa & Vật liệu', 'Filament PLA, PETG, ABS, TPU và resin chính hãng.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/3D_printing_filament.jpg/1280px-3D_printing_filament.jpg', 4),
('phu-kien-linh-kien', 'Phụ kiện & Linh kiện', 'Đầu phun, bàn nhiệt, giá đỡ cuộn nhựa và dụng cụ hoàn thiện.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Hardened_Steel_3D_Printing_Nozzle.jpg/1280px-Hardened_Steel_3D_Printing_Nozzle.jpg', 5);

